BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Contradictory evidence vs. management representations
(1, 'Written Representations', 'During the audit of Greystone Manufacturing for the year ended December 31, 2025, the engagement team at Crawford & Associates discovers audit evidence that directly contradicts a written representation from management regarding the completeness of inventory. Under AU-C 580, how should the auditor analyze this situation?', '["The auditor should reconsider the reliability of all written representations and determine whether the audit opinion may be affected", "The auditor should accept the written representation because management has primary authority over financial statement assertions", "The auditor should disregard the written representation and rely exclusively on the contradictory audit evidence", "The auditor should request a revised representation letter that removes the conflicting representation"]'::jsonb, 0, 'Under AU-C 580.A23, when audit evidence contradicts a written representation, the auditor should reconsider the reliability of other representations and evaluate the effect on the audit opinion. Written representations do not substitute for other evidence, and contradictions raise questions about management''s overall integrity. Choice B is incorrect because accepting a contradicted representation without further investigation would fail to exercise the professional skepticism required throughout the engagement.', 'medium', 3),

-- Q2: medium / L2 — Period covered by representation letter
(1, 'Written Representations', 'Whitaker & Partners CPAs audits the comparative financial statements of Brookstone Enterprises for the years ended December 31, 2024, and December 31, 2025. The auditor''s report covers both years. The engagement partner asks the staff to prepare the representation letter. Under AU-C 580, the management representation letter should cover:', '["Only the most recent fiscal year ended December 31, 2025", "All periods covered by the auditor''s report, including both fiscal years 2024 and 2025", "Only the period from the prior year''s report date through December 31, 2025", "The most recent year plus any subsequent events through the report date"]'::jsonb, 1, 'Under AU-C 580.14, the management representation letter must cover all periods referred to in the auditor''s report. Because the report covers comparative financial statements for both 2024 and 2025, the representations must address both fiscal years. Choice A is incorrect because limiting representations to only the current year would leave the auditor without written support for assertions about the prior-period financial statements included in the report.', 'medium', 2),

-- Q3: medium / L2 — Representation about accounting policies
(1, 'Written Representations', 'During the December 31, 2025 audit of Maplewood Healthcare Group, the engagement team at Sterling & Klein CPAs drafts the management representation letter. The controller asks which representation is required regarding accounting policies. Under AU-C 580, management must represent that:', '["The entity''s accounting policies have been approved by the external auditors before implementation", "All accounting policies were established solely by the audit committee without management involvement", "The significant accounting policies selected and applied are appropriate for the entity''s financial reporting framework", "Accounting policies have remained unchanged from the prior year and require no further disclosure"]'::jsonb, 2, 'Under AU-C 580.11, management must provide a written representation that the significant accounting policies are appropriate for the applicable financial reporting framework. This does not require auditor pre-approval or mandate that policies remain unchanged. Choice A is incorrect because accounting policy selection is management''s responsibility, not the auditor''s.', 'medium', 2),

-- Q4: easy / L1 — Addressee of the representation letter
(1, 'Written Representations', 'Under AU-C 580, the management representation letter is addressed to:', '["The entity''s board of directors", "The entity''s audit committee", "The Securities and Exchange Commission", "The engagement auditor"]'::jsonb, 3, 'Under AU-C 580.15, the management representation letter is addressed to the auditor. The letter is a formal communication from management to the engagement team confirming key assertions that support the audit. While the audit committee oversees the audit process, Choice B is incorrect because the representation letter is a direct communication between management and the auditor, not addressed to the audit committee or other governance body.', 'easy', 1),

-- Q5: easy / L1 — Written vs. oral representations
(1, 'Written Representations', 'Under AU-C 580, why does the auditor require written representations from management rather than accepting oral assurances?', '["Written representations reduce misunderstandings and provide a formal record that management has considered the representations carefully", "Oral representations are prohibited by generally accepted auditing standards under all circumstances", "Written representations constitute sufficient appropriate audit evidence on their own without additional corroboration", "The SEC mandates that all management communications to auditors be in writing"]'::jsonb, 0, 'Under AU-C 580.A4, written representations reduce the possibility of misunderstandings between management and the auditor. Putting representations in writing formalizes the process and encourages management to consider the matters more carefully than informal oral discussion. Choice B is incorrect because oral inquiry of management is a valid audit procedure under AU-C 500; written form is specifically required for the representation letter.', 'easy', 1),

-- Q6: easy / L1 — Representation about internal control responsibility
(1, 'Written Representations', 'Which of the following is a required written representation under AU-C 580 regarding internal controls?', '["Management has implemented all controls recommended by the auditor during the prior engagement", "The entity''s internal controls have eliminated the risk of material misstatement", "Management acknowledges its responsibility for the design, implementation, and maintenance of internal control relevant to financial reporting", "The audit committee has independently tested all internal controls during the current period"]'::jsonb, 2, 'Under AU-C 580.11, management must provide a written representation acknowledging its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation of financial statements. This does not require management to implement auditor recommendations or claim controls eliminate all risk. Choice A is incorrect because management has sole authority to determine which controls to implement, regardless of auditor recommendations.', 'easy', 1),

-- Q7: easy / L1 — Written representations as necessary but not sufficient
(1, 'Written Representations', 'Under AU-C 580, written representations from management are classified as which type of audit evidence?', '["Sufficient appropriate audit evidence that can replace all other substantive procedures", "Necessary audit evidence that alone does not provide sufficient appropriate audit evidence", "External evidence because the letter is signed by parties outside the audit engagement", "Corroborative evidence that is only obtained when other evidence is unavailable"]'::jsonb, 1, 'Under AU-C 580.04, written representations are necessary information that the auditor requires, but they do not provide sufficient appropriate audit evidence on their own about any of the matters with which they deal. The representations are internal evidence from management, not external, and are required in every audit, not just when other evidence is unavailable. Choice A is incorrect because representations cannot substitute for other audit procedures.', 'easy', 1),

-- Q8: hard / L4 — Evaluating reliability when representations contradict known facts
(1, 'Written Representations', 'During the audit of Summit Ridge Financial Corp. for the year ended December 31, 2025, the engagement partner at Thornton & Associates discovers that management''s written representation about the completeness of litigation disclosures is contradicted by a letter from outside legal counsel identifying a $4.2 million pending lawsuit not disclosed to the auditors. Management states the omission was an oversight. Under AU-C 580, what is the most appropriate course of action?', '["Accept management''s explanation and request an amended representation letter that adds the litigation disclosure", "Issue a qualified opinion based solely on the identified litigation omission without further investigation", "Withdraw the written representation requirement for litigation since legal counsel has provided the information directly", "Reassess the reliability of all management representations, perform additional audit procedures to evaluate the completeness of other representations, and consider the effect on the audit opinion"]'::jsonb, 3, 'Under AU-C 580.A23, when the auditor identifies contradictions between representations and other audit evidence, the auditor must reconsider the reliability of all written representations and evaluate whether they can continue to rely on management''s integrity. A single oversight may indicate broader issues. Choice A is incorrect because merely amending the letter does not address the fundamental reliability concern or the need for expanded audit procedures across all assertion areas.', 'hard', 4),

-- Q9: medium / L2 — Going concern representation
(1, 'Written Representations', 'Prescott & Lang CPAs is completing the audit of Cascade Valley Hotels for the year ended December 31, 2025. The entity has experienced declining occupancy rates and negative cash flows for three consecutive quarters. The engagement partner requires a written representation about going concern. Under AU-C 580, management should represent that:', '["The entity will continue operations for at least 24 months beyond the balance sheet date without any need for additional financing", "The auditor bears primary responsibility for evaluating whether the entity can continue as a going concern", "Management''s plans to address conditions that raise substantial doubt about the entity''s ability to continue as a going concern are disclosed in the financial statements", "The going concern assumption is validated by the entity''s creditors and does not require management evaluation"]'::jsonb, 2, 'Under AU-C 580.11 and AU-C 570, management must represent that its plans regarding going concern conditions and events are appropriately disclosed in the financial statements. The representation period is generally one year from the financial statement date, not 24 months. Choice A is incorrect because the standard does not require management to guarantee a specific timeline; management must disclose its plans and any conditions raising substantial doubt.', 'medium', 2),

-- Q10: medium / L3 — Effect of uncorrected misstatements representation
(1, 'Written Representations', 'The audit team at Kessler & Monroe identifies $38,000 in aggregate uncorrected misstatements during the December 31, 2025 audit of Pinehurst Distribution Inc., with overall materiality set at $50,000. Management signs a representation stating that the uncorrected misstatements are immaterial both individually and in the aggregate. What is the most likely effect of this representation on the auditor''s analysis?', '["The representation supports the auditor''s conclusion that the misstatements are immaterial, but the auditor must independently evaluate whether the aggregate is truly below materiality", "The representation eliminates the auditor''s responsibility for evaluating uncorrected misstatements since management has accepted responsibility for them", "The representation requires the auditor to lower overall materiality to $38,000 to match the identified misstatements", "The representation triggers a scope limitation because management should have corrected all identified misstatements"]'::jsonb, 0, 'Under AU-C 580.11 and AU-C 450.11, management must represent that the effects of uncorrected misstatements are immaterial to the financial statements. However, this representation does not relieve the auditor of the obligation to independently evaluate whether uncorrected misstatements are material individually or in aggregate. Choice B is incorrect because the auditor retains professional responsibility for assessing materiality regardless of management''s assertion.', 'medium', 3),

-- Q11: medium / L3 — Subsequent events representation in the rep letter
(1, 'Written Representations', 'The auditor at Bradshaw & Associates is finalizing the representation letter for the December 31, 2025 audit of Lakeshore Realty Group. The auditor''s report will be dated March 10, 2026. The engagement partner asks which subsequent events representation should be included. Under AU-C 580, how should the subsequent events representation be analyzed?', '["The representation should cover only events occurring before the balance sheet date of December 31, 2025", "The representation should cover events through the date the representation letter is provided to the auditor, regardless of the report date", "The representation is unnecessary because subsequent events are covered entirely by AU-C 560 procedures", "The representation should address events occurring between the balance sheet date and the report date that require adjustment or disclosure in the financial statements"]'::jsonb, 3, 'Under AU-C 580.11 and AU-C 560, management must represent that all events occurring between the balance sheet date and the date of the auditor''s report that require adjustment or disclosure have been properly reflected. The representation specifically covers the subsequent events period. Choice A is incorrect because limiting the representation to pre-balance sheet events would leave the critical subsequent events period uncovered.', 'medium', 3),

-- Q12: easy / L2 — Representation about access to records
(1, 'Written Representations', 'During the December 31, 2025 audit of Ridgeway Partners LLC, the engagement team at Foster & Hale CPAs prepares the management representation letter. Under AU-C 580, which representation regarding access to information must management provide?', '["Management certifies that the auditor has examined every document maintained by the entity during the audit period", "Management has provided the auditor with access to all information relevant to the financial statements and has disclosed all matters of which management is aware", "Management has restricted auditor access only to information directly related to account balances tested during fieldwork", "Management has forwarded all entity records to the auditor''s office for permanent retention in the audit file"]'::jsonb, 1, 'Under AU-C 580.11, management must represent that it has provided the auditor with all relevant information and access as agreed in the engagement letter, and has disclosed all matters it is aware of that are relevant to the audit. This is a completeness representation, not a guarantee of exhaustive review. Choice A is incorrect because the representation addresses management''s obligation to make information available, not a claim that the auditor examined every document.', 'easy', 2),

-- Q13: medium / L3 — Representations in group audits
(1, 'Written Representations', 'Morrison & Tate CPAs serves as the group engagement partner for the consolidated audit of Horizon Global Corp. for the year ended December 31, 2025. The group includes three subsidiaries, each audited by different component auditors. The group partner evaluates what written representations are needed. Under AU-C 600 and AU-C 580, how should the requirement for management representations be analyzed?', '["Only the parent company''s management is required to provide written representations; component management representations are optional", "The component auditors must obtain representations from group management rather than from their respective component management teams", "The group engagement partner should request representations from group management, and component auditors should obtain representations from component management for their respective components", "Written representations are waived for components that represent less than 15% of consolidated revenue"]'::jsonb, 2, 'Under AU-C 600.41 and AU-C 580, in a group audit, both group management and component management should provide written representations appropriate to their respective levels. The group engagement partner obtains representations from group management covering the consolidated financial statements, while component auditors obtain representations from component management. Choice A is incorrect because omitting component management representations would leave significant assertions uncorroborated at the component level.', 'medium', 3),

-- Q14: easy / L1 — Representation about title to assets
(1, 'Written Representations', 'Under AU-C 580, which written representation addresses the rights and obligations assertion?', '["Management represents that all assets are recorded at fair market value as of the balance sheet date", "Management represents that the entity has satisfactory title to all owned assets and that liens or pledges are properly disclosed", "Management represents that all assets have been physically inspected by independent appraisers during the current year", "Management represents that asset depreciation rates were established by the external auditor"]'::jsonb, 1, 'Under AU-C 580.11, management must provide representations that the entity has satisfactory title to assets and that all liens, encumbrances, or pledges of assets are properly disclosed. This representation directly supports the rights and obligations assertion. Choice A is incorrect because the representation about title addresses ownership rights, not the valuation method applied to assets.', 'easy', 1),

-- Q15: hard / L4 — Evaluating when management lacks competence
(1, 'Written Representations', 'During the audit of Northfield Biotech Inc. for the year ended December 31, 2025, the engagement partner at Ellison & Cross CPAs notes that the company recently replaced its entire accounting staff. The new controller has been in the role for only six weeks and openly admits unfamiliarity with several complex accounting areas, including derivative instruments and revenue recognition policies. The partner must evaluate how management''s competence affects written representations. Under AU-C 580, what course of action should the partner recommend?', '["Waive the written representation requirement for areas where the controller lacks expertise since the representations would be meaningless", "Accept the representations without modification because the controller holds the title of chief accounting officer", "Delay issuing the audit report until the controller has completed at least six months in the role", "Obtain the required representations from the controller and CEO, perform expanded substantive procedures in complex areas, and evaluate whether the lack of expertise constitutes a control deficiency"]'::jsonb, 3, 'Under AU-C 580.A2 and AU-C 580.09, the auditor cannot waive written representations regardless of management''s expertise level, but must consider whether management''s competence affects the reliability of those representations. The auditor should obtain the required representations and supplement them with additional substantive procedures. Choice A is incorrect because AU-C 580 does not permit waiving required representations; instead, the auditor must assess the impact on the overall audit approach and consider reporting control deficiencies.', 'hard', 4),

-- Q16: medium / L2 — Laws and regulations representation
(1, 'Written Representations', 'Franklin & Reeves CPAs is auditing Sentinel Healthcare Systems for the year ended December 31, 2025. The engagement team is drafting the representation letter for an entity operating in a heavily regulated industry. Under AU-C 580 and AU-C 250, the representation about laws and regulations should state that management has:', '["Disclosed to the auditor all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered in preparing the financial statements", "Obtained legal opinions from outside counsel confirming full compliance with every applicable federal and state regulation", "Delegated all regulatory compliance monitoring to the external auditor as part of the engagement scope", "Certified that zero violations of any law or regulation occurred during the fiscal year"]'::jsonb, 0, 'Under AU-C 580.11 and AU-C 250, management must represent that all known instances of noncompliance or suspected noncompliance with laws and regulations whose effects should be considered when preparing financial statements have been disclosed to the auditor. This is a disclosure obligation, not a compliance guarantee. Choice D is incorrect because the representation requires disclosure of known noncompliance, not a blanket certification that no violations occurred.', 'medium', 2),

-- Q17: medium / L2 — Completeness of contingent liabilities representation
(1, 'Written Representations', 'During the December 31, 2025 audit of Atlas Logistics Corp., the engagement team at Davenport & Knox CPAs prepares the management representation letter. Atlas is involved in multiple contractual disputes with vendors. Under AU-C 580, which representation should management provide regarding contingent liabilities?', '["Management has certified that no contingent liabilities exist as of the balance sheet date", "Management represents that the auditor has independently identified all contingent liabilities without any input from management", "Management has disclosed all known contingencies and provided its best estimate of the range of potential losses where estimable", "Management certifies that outside legal counsel has confirmed the resolution of all pending disputes before year-end"]'::jsonb, 2, 'Under AU-C 580.11 and AU-C 501, management must represent that it has disclosed all known contingent liabilities, including information about litigation, claims, and assessments. Where a reasonable estimate can be made, management should provide its best estimate of the potential range of loss. Choice A is incorrect because the representation addresses disclosure and estimation of known contingencies, not a certification that no contingencies exist.', 'medium', 2),

-- Q18: easy / L1 — Engagement letter vs. representation letter timing
(1, 'Written Representations', 'How does the management representation letter differ from the engagement letter in terms of timing?', '["Both letters are issued before the audit begins and serve the same purpose", "The management representation letter is issued before fieldwork; the engagement letter is issued at the audit''s conclusion", "The engagement letter is signed by the auditor; the management representation letter is also signed by the auditor", "The engagement letter is obtained at the start of the engagement, while the management representation letter is obtained near the audit''s conclusion"]'::jsonb, 3, 'Under AU-C 210 and AU-C 580, the engagement letter establishes the terms of the audit at the outset, while the management representation letter is obtained near the end of the audit as of the report date. The engagement letter is agreed to by both parties before work begins; the representation letter is a communication from management to the auditor confirming assertions. Choice B reverses the timing of both documents.', 'easy', 1),

-- Q19: medium / L3 — Effect of representation about estimates
(1, 'Written Representations', 'The audit team at Clifford & Webb CPAs is reviewing the management representation letter for the December 31, 2025 audit of Meridian Insurance Group. Management''s representation states that the assumptions used in actuarial estimates for claim reserves are reasonable. However, the auditor''s independent analysis shows that one key assumption deviates significantly from industry experience. What is the most likely effect on the auditor''s analysis?', '["The representation validates the estimate, and the auditor should accept the claim reserves as presented", "The representation does not override the auditor''s independent evaluation; the auditor should investigate the deviation and may request management to revise the assumption", "The representation shifts liability for the estimate entirely to management, relieving the auditor of further evaluation responsibility", "The representation requires the auditor to hire an independent actuary before forming any conclusion about the reserves"]'::jsonb, 1, 'Under AU-C 580.04 and AU-C 540, written representations about the reasonableness of estimates do not substitute for the auditor''s independent evaluation of the methods, data, and assumptions used. When the auditor identifies a significant deviation from industry experience, further investigation is warranted regardless of management''s representation. Choice A is incorrect because the auditor has an independent obligation to evaluate estimates and cannot defer to management''s assertion of reasonableness.', 'medium', 3),

-- Q20: hard / L4 — Evaluating qualified representations
(1, 'Written Representations', 'During the December 31, 2025 audit of Bridgewater Capital Partners, the CFO requests that the management representation letter include a qualification stating: ''To the best of our knowledge, except for the valuation of the Level 3 portfolio holdings, all representations are accurate.'' The engagement partner at Kimball & Associates evaluates whether this qualification is acceptable. Under AU-C 580, what should the engagement partner recommend?', '["Accept the qualification because management has legitimate uncertainty about Level 3 valuations and the qualification reflects honest disclosure", "Modify the audit report to include an emphasis-of-matter paragraph referencing the qualified representation", "Issue an unmodified opinion since the Level 3 holdings are disclosed as estimates in the financial statement notes", "Evaluate whether the carve-out represents an inability to provide required representations, perform additional procedures on Level 3 valuations, and consider the effect on the audit opinion if the representation cannot be obtained without qualification"]'::jsonb, 3, 'Under AU-C 580.20, when management qualifies written representations, the auditor should evaluate whether the qualification creates an inability to provide required representations. A blanket carve-out for an entire asset class raises concerns about whether the auditor can obtain sufficient appropriate evidence. Choice A is incorrect because accepting a broadly worded qualification without investigation would undermine the purpose of written representations and may constitute a scope limitation.', 'hard', 4),

-- Q21: medium / L2 — Side agreements representation
(1, 'Written Representations', 'Hartley & Simmons CPAs is auditing Crestwood Retail Group for the year ended December 31, 2025. During the audit, the partner learns that Crestwood frequently uses vendor consignment arrangements. The partner adds a specific representation about side agreements. Under AU-C 580, management should represent that:', '["There are no side agreements, oral or written, that modify the terms of disclosed contracts or arrangements unless already communicated to the auditor", "All vendor agreements have been reviewed and approved by the external auditor before execution", "Side agreements are permissible and do not need to be disclosed as long as they involve amounts below materiality", "The auditor is responsible for independently discovering all side agreements through substantive testing"]'::jsonb, 0, 'Under AU-C 580.11, management must represent that there are no undisclosed side agreements or arrangements that would affect the financial statements. Side agreements can modify the economic substance of reported transactions, making their disclosure critical. Choice C is incorrect because side agreements must be disclosed to the auditor regardless of dollar amount, as even individually immaterial arrangements could indicate broader concerns about management''s transparency.', 'medium', 2),

-- Q22: medium / L3 — Governance-level representations
(1, 'Written Representations', 'The engagement partner at Dawson & Fairchild CPAs is completing the audit of Oceanview Properties Inc. for the year ended December 31, 2025. Management has provided the standard representation letter, but the partner notes that the board of directors approved a significant related-party transaction that management did not disclose until the final week of fieldwork. The partner evaluates whether to request additional representations from those charged with governance. What factor most likely supports requesting governance-level representations?', '["Governance-level representations are required for every audit engagement regardless of the circumstances", "Governance representations are only needed when the entity is a governmental organization or nonprofit", "The late disclosure of a significant related-party transaction raises concerns about whether management has been forthcoming, and governance representations may corroborate management''s completeness assertions", "Governance representations are needed only when management has formally refused to sign the representation letter"]'::jsonb, 2, 'Under AU-C 580.13 and AU-C 260, when circumstances suggest management may not have been transparent — such as the late disclosure of a significant related-party transaction — the auditor may determine that representations from those charged with governance are appropriate to corroborate management''s assertions. Choice A is incorrect because governance-level representations are not mandatory for every audit; they are requested when circumstances warrant additional assurance beyond management''s representations.', 'medium', 3),

-- Q23: hard / L4 — Evaluating inability vs. refusal to provide representations
(1, 'Written Representations', 'During the December 31, 2025 audit of Pacific West Energy Corp., the CEO informs the engagement partner at Voss & Kendall CPAs that the company cannot provide the standard written representation about the completeness of environmental liabilities because the company''s environmental consultants have not completed their assessment. The CEO assures the partner that no environmental issues exist to the CEO''s knowledge. Under AU-C 580, which response best reflects professional judgment?', '["Accept the CEO''s oral assurance as equivalent to a written representation because the CEO is the highest authority in the organization", "Distinguish between an inability to provide the representation and a refusal, evaluate whether the incomplete assessment constitutes a reasonable basis for the inability, consider extending the report date, and determine the impact on the audit opinion", "Immediately disclaim the audit opinion because any failure to obtain a written representation requires a disclaimer regardless of the circumstances", "Remove the environmental liability representation from the letter and proceed with an unmodified opinion on all other financial statement areas"]'::jsonb, 1, 'Under AU-C 580.19–.20, the auditor must distinguish between management''s inability and refusal to provide written representations. If management cannot provide a representation because a third-party assessment is incomplete, the auditor should evaluate whether the reason is legitimate, consider whether extending the timeline would resolve the issue, and assess the effect on the audit opinion. Choice C is incorrect because a disclaimer is required when management refuses required representations, not necessarily when there is a documented inability that may be resolvable.', 'hard', 4),

-- Q24: hard / L4 — Evaluating completeness of related-party representation
(1, 'Written Representations', 'The engagement partner at Sinclair & Wade CPAs is reviewing the management representation letter for Apex Holdings Group''s December 31, 2025 audit. Management represents that all related-party relationships and transactions have been disclosed. However, the audit team identified a previously undisclosed entity controlled by the CEO''s spouse that had $1.8 million in transactions with Apex during the year. Management claims the omission was unintentional. What course of action reflects the strongest professional judgment?', '["Accept management''s explanation, add the newly identified entity to the related-party disclosures, and obtain an updated representation letter", "Report the undisclosed related party to the SEC as a potential fraud indicator without further investigation", "Issue a qualified opinion solely based on the initial omission of the related-party disclosure", "Reassess the risk of material misstatement due to fraud, perform expanded related-party procedures to determine whether additional undisclosed parties exist, evaluate management''s integrity, and consider the implications for all written representations"]'::jsonb, 3, 'Under AU-C 580.A23 and AU-C 550, discovering an undisclosed related party with material transactions after management has represented completeness raises serious concerns about management''s integrity and the reliability of other representations. The auditor must reassess fraud risk, expand related-party procedures, and evaluate the effect on all representations. Choice A is incorrect because simply amending the disclosures ignores the reliability implications of the initial omission and the auditor''s heightened responsibility under AU-C 240 regarding fraud risk.', 'hard', 4),

-- Q25: medium / L3 — Plans and intentions affecting carrying values
(1, 'Written Representations', 'During the December 31, 2025 audit of Westbrook Manufacturing Inc., the engagement team at Palmer & Doyle CPAs notes that management''s representation letter states management intends to hold a manufacturing facility for continued use rather than sell it. The facility''s carrying value exceeds its fair value by $2.3 million. Under AU-C 580 and ASC 360, what is the most likely effect of this representation on the auditor''s analysis?', '["The representation about management''s intent is relevant because it affects whether an impairment test uses the held-and-used model versus the held-for-sale model, but the auditor must corroborate the intent with other evidence such as capital budgets and board minutes", "The representation eliminates the need for any impairment analysis because management has affirmed continued use", "The representation is irrelevant because asset valuation is determined solely by market prices and does not depend on management''s plans", "The representation triggers an automatic impairment write-down because the carrying value exceeds fair value regardless of intent"]'::jsonb, 0, 'Under AU-C 580 and ASC 360-10-35, management''s intent to hold or dispose of a long-lived asset determines which impairment model applies. A written representation about intent is relevant but must be corroborated with other evidence such as capital expenditure plans, board minutes, and operational forecasts. Choice B is incorrect because a representation about continued use does not eliminate the need for impairment testing — the auditor must still evaluate whether the asset''s carrying amount is recoverable under the held-and-used model.', 'medium', 3),

-- Q26: medium / L2 — Fair value measurements representation
(1, 'Written Representations', 'Thornberry & Associates CPAs is completing the audit of Pinnacle Asset Management for the year ended December 31, 2025. Pinnacle holds $45 million in Level 3 financial instruments measured at fair value. Under AU-C 580 and AU-C 540, management should represent that:', '["The auditor has independently verified all fair value measurements and approved the valuation methodologies used by the entity", "Fair value measurements are only required for financial instruments that are publicly traded on an active exchange", "Management has outsourced all fair value measurements to third-party valuation specialists, thereby transferring responsibility to those specialists", "The measurement methods, significant assumptions, and data used in determining fair values are appropriate and consistently applied within the applicable financial reporting framework"]'::jsonb, 3, 'Under AU-C 580.11 and AU-C 540, management must represent that the methods, assumptions, and data underlying fair value measurements are appropriate and consistent with the applicable framework. Even when management uses third-party specialists, management retains responsibility for the measurements. Choice C is incorrect because outsourcing valuation work to specialists does not transfer management''s ultimate responsibility for fair value measurements in the financial statements.', 'medium', 2),

-- Q27: easy / L1 — Management's responsibility for fair presentation
(1, 'Written Representations', 'Under AU-C 580, what fundamental responsibility must management acknowledge in the written representation letter?', '["Responsibility for selecting the audit firm and determining the scope of audit procedures", "Responsibility for the preparation and fair presentation of the financial statements in accordance with the applicable financial reporting framework", "Responsibility for issuing the auditor''s report and determining the type of audit opinion", "Responsibility for establishing generally accepted accounting principles applicable to the entity''s industry"]'::jsonb, 1, 'Under AU-C 580.11, one of the foundational written representations is management''s acknowledgment of its responsibility for the preparation and fair presentation of the financial statements. This reinforces that the financial statements are management''s responsibility, not the auditor''s. Choice A is incorrect because while management selects the audit firm, the representation letter focuses on responsibility for the financial statements, not engagement logistics.', 'easy', 1),

-- Q28: easy / L1 — Additional entity-specific representations
(1, 'Written Representations', 'Under AU-C 580, beyond the standard representations, may the auditor request additional written representations specific to the entity?', '["Yes, the auditor may request additional representations relevant to the entity''s specific circumstances and risks identified during the audit", "No, the auditor may only request the specific representations listed in AU-C 580 and no others", "Yes, but only if the additional representations are approved by the entity''s audit committee in advance", "No, any additional representations must be obtained through a separate letter unrelated to the standard representation letter"]'::jsonb, 0, 'Under AU-C 580.A11, the auditor may determine that additional written representations beyond those explicitly required are necessary based on the nature and circumstances of the engagement. These additional representations address entity-specific risks or unusual transactions identified during the audit. Choice B is incorrect because AU-C 580 provides a minimum set of required representations but does not restrict the auditor from requesting additional relevant representations.', 'easy', 1),

-- Q29: medium / L2 — Commitments and contractual obligations representation
(1, 'Written Representations', 'During the December 31, 2025 audit of Redstone Construction Corp., the engagement team at Barrett & Hughes CPAs discovers that Redstone has entered into a $12 million construction contract obligating the company to significant future expenditures. Under AU-C 580, management should represent that:', '["The auditor is solely responsible for identifying all material contractual obligations through independent investigation", "Contractual obligations need only be disclosed if payments are due within 30 days of the balance sheet date", "All material commitments and contractual obligations have been disclosed in the financial statements or notes, including the $12 million construction contract", "Management has obtained written consent from all contracting parties before disclosing contract terms to the auditor"]'::jsonb, 2, 'Under AU-C 580.11, management must represent that all significant commitments and contractual obligations are properly identified and disclosed in the financial statements. This includes long-term contracts that may require disclosure under the applicable financial reporting framework. Choice B is incorrect because the representation covers all material commitments regardless of payment timing, not just those due within a short period after year-end.', 'medium', 2),

-- Q30: hard / L3 — Representation requirements for reissued reports
(1, 'Written Representations', 'Kendrick & Shaw CPAs originally audited Vanguard Technologies'' financial statements for the year ended December 31, 2024, and issued their report on March 1, 2025. In February 2026, Vanguard requests the auditor to reissue the 2024 report for inclusion in a debt offering document. Under AU-C 580 and AU-C 560, how should the representation requirements for a reissued report be analyzed?', '["The auditor should obtain a new representation letter from management covering the period from the original report date through the reissuance date, addressing whether any information has come to management''s attention that would cause the previously issued financial statements to be revised", "The original representation letter from March 2025 remains valid and no additional representations are needed for the reissuance", "Management representations are not required when a report is reissued because the audit was already completed in the prior period", "The auditor should only request an oral confirmation from the CFO that no changes have occurred since the original audit"]'::jsonb, 0, 'Under AU-C 580 and AU-C 560.12–.13, when reissuing a previously issued report, the auditor should obtain updated written representations from management covering the period from the original report date through the reissuance date. Management must represent whether any information has arisen that would affect the previously issued financial statements. Choice B is incorrect because the passage of time since the original report creates a period during which new events or discoveries may have affected the financial statements, requiring fresh representations.', 'hard', 3)
;

COMMIT;
